ClearAll[eta,b,v,m,u0,w0,q,mu,kt,hh,ss,pis,hlog,beta,pm0];
u=u0 Exp[-2 eta+2 b]; w=w0 Exp[-2 eta-4 b];
ee=Sqrt[m^2+u+w]; wt=Exp[-3 eta];
dAlong[f_]:=D[f,eta]+v D[f,b];
rho=wt ee; pp=wt u/(2 ee); pa=wt w/ee; pi=(pa-pp)/3;
du=(-2+2 v)u; dw=(-2-4 v)w; de=(du+dw)/(2 ee);
predRho=wt(-3 ee+de);
predPp=wt((-3 u+du)/(2 ee)-u de/(2 ee^2));
predPa=wt((-3 w+dw)/ee-w de/ee^2);
assum=m>0&&u0>=0&&w0>=0&&Element[{eta,b,v},Reals];
checks=FullSimplify[{dAlong[rho]-predRho,dAlong[pp]-predPp,dAlong[pa]-predPa,dAlong[rho]+3(rho+(2pp+pa)/3)+6v pi},Assumptions->assum];
initialPi=Exp[-5 eta] q^2(3mu^2-1)/(6 Sqrt[m^2+Exp[-2 eta]q^2]);
pi0=initialPi/.eta->0;
initialChecks=FullSimplify[{(D[initialPi,eta]/.eta->0)-(-5+q^2/(m^2+q^2))pi0,(D[initialPi,eta]/.eta->0)+4pi0+m^2 q^2(3mu^2-1)/(6(m^2+q^2)^(3/2))},Assumptions->m>0&&q>0&&Element[mu,Reals]];
shearIdentity=FullSimplify[Sqrt[6](-3ss+kt pis/hh)/hh-Sqrt[6]ss hlog/hh-(Sqrt[6]kt pis/hh^2-(3+hlog)Sqrt[6]ss/hh),Assumptions->hh>0];
jet=-(1-beta)pm0/2;
<|"mass_shell_derivative_residuals"->checks,"initial_redshift_residuals"->initialChecks,"normalized_shear_identity_residual"->shearIdentity,"ideal_S_eta2_coefficient"->jet,"SI_identity_residual"->FullSimplify[(8 Pi g/c^2)/hh^2-(8 Pi g/c^4)/(hh/c)^2,Assumptions->c>0&&hh>0]|>
